  { const p = a.waterRule, q = b.waterRule; if (p === null || p === undefined || q === null || q === undefined) { if (p !== q) return ".waterRule"; } else { { const d = sameWaterRule(p, q); if (d) return ".waterRule" + d; } } }
  if (!Object.is(a.waterDepth, b.waterDepth)) return ".waterDepth";
  if (!Object.is(a.body, b.body)) return ".body";
  if (!sameVec(a.position, b.position)) return ".position";
  if (!sameVec(a.previous, b.previous)) return ".previous";
  if (!sameVec(a.velocity, b.velocity)) return ".velocity";
  if (!Object.is(a.yaw, b.yaw)) return ".yaw";
