  if (!Object.is(a.tiltRate, b.tiltRate)) return ".tiltRate";
  if (!Object.is(a.rollRate, b.rollRate)) return ".rollRate";
  if (!Object.is(a.support, b.support)) return ".support";
  if (!Object.is(a.forwardInput, b.forwardInput)) return ".forwardInput";
  if (!Object.is(a.rightInput, b.rightInput)) return ".rightInput";
  if (!Object.is(a.alive, b.alive)) return ".alive";
  { const p = a.sleeping, q = b.sleeping; if (p === null || p === undefined || q === null || q === undefined) { if (p !== q) return ".sleeping"; } else { if (!Object.is(p, q)) return ".sleeping"; } }
  if (!Object.is(a.health, b.health)) return ".health";
  if (!Object.is(a.dying, b.dying)) return ".dying";
