export function exportVehicle(o, cx) {
  let v = cx.seen.get(o);
  if (v) return v;
  v = {};
  cx.seen.set(o, v);
  v.$id = cx.ref("vehicle", o);
  v.name = o.name;
  v.flying = o.flying;
  v.walking = o.walking;
  v.creature = o.creature;
  v.wheeled = o.wheeled;
  v.repulsor = o.repulsor;
  v.speed = o.speed;
  v.reverseSpeed = o.reverseSpeed;
  v.strafeSpeed = o.strafeSpeed;
  v.acceleration = o.acceleration;
  v.deceleration = o.deceleration;
  v.turnRate = o.turnRate;
  v.hover = o.hover;
  v.boundsMin = o.bounds?.min.clone();
  v.boundsMax = o.bounds?.max.clone();
  v.center = o.center.clone();
  v.size = o.size.clone();
  v.boundRadius = o.boundRadius;
  v.probeRadius = o.probeRadius;
  v.probes = o.probes.map((x) => x.clone());
  v.supportProbes = o.supportProbes.map((x) => x.clone());
  v.maxHealth = o.maxHealth;
  v.waterRule = ((x) => (x === null || x === undefined ? x : exportWaterRule(x, cx)))(o.waterRule);
  v.waterDepth = o.waterDepth;
  v.body = cx.ref("body", o.body);
  v.position = o.position.clone();
  v.previous = o.previous.clone();
  v.velocity = o.velocity.clone();
  v.yaw = o.yaw;
  v.previousYaw = o.previousYaw;
  v.tilt = o.tilt;
  v.roll = o.roll;
  v.previousTilt = o.previousTilt;
  v.previousRoll = o.previousRoll;
  v.yawRate = o.yawRate;
  v.tiltRate = o.tiltRate;
  v.rollRate = o.rollRate;
  v.support = o.support;
  v.forwardInput = o.forwardInput;
  v.rightInput = o.rightInput;
  v.alive = o.alive;
  v.sleeping = o.sleeping;
  v.health = o.health;
  v.dying = o.dying;
  v.waterClock = o.waterClock;
  v.quaternion = o.quaternion.clone();
  v.matrix = o.matrix.clone();
  v.itemCenter = o.itemTarget?.center.clone();
  v.supportNormal = o.supportNormal.clone();
  v.legSide = ((x) => (x === null || x === undefined ? x : x.map((x) => x)))(o.legSide);
  v.seatIndex = o.seatIndex;
  v.driver = ((x) => (x === null || x === undefined ? x : cx.ref("vehicleDriver", x)))(o.driver);
  v.wheels = o.wheels.map((x) => exportVehicleWheel(x, cx));
  v.seats = o.seats.map((x) => exportVehicleSeat(x, cx));
  return v;
}

// vehicles: from rust/sim/schema/vehicles.mjs.
export class VehiclesMirror {
  constructor() {
    this.vehicles = [];
  }
}

export const VEHICLES_KEYS = new Set(["vehicles"]);
export const VEHICLES_EXPORT_STRIDE = 4, VEHICLES_IMPORT_STRIDE = 4, VEHICLES_FULL_STRIDE = 4;

// An export row (from `at`; the heap from `h`) into mirror `m`.
export function syncVehicles(b, f, at, h, m) {
  { const items = (m.vehicles ??= []), start = h + f[at + 2], n = f[at + 3]; items.length = n; for (let i = 0; i < n; i++) { let v = items[i]; { const at = start + i * 2; v = b.refs[KIND_VEHICLE].at(f[at + 0], f[at + 1]); } items[i] = v; } }
  return m;
}

// A full row into object `m`.
export function syncFullVehicles(b, f, at, h, m) {
  { const items = (m.vehicles ??= []), start = h + f[at + 2], n = f[at + 3]; items.length = n; for (let i = 0; i < n; i++) { let v = items[i]; { const at = start + i * 2; v = b.refs[KIND_VEHICLE].at(f[at + 0], f[at + 1]); } items[i] = v; } }
  return m;
}

// Object `o`'s import fields into a row (lists to `heap`).
export function putVehicles(b, o, f, at, heap) {
  heap.items(o.vehicles, f, at + 2, 2, (f, at, v) => { b.refs[KIND_VEHICLE].put(v, f, at + 0); });
}

// Every field of object `o` into a row.
export function putFullVehicles(b, o, f, at, heap) {
  heap.items(o.vehicles, f, at + 2, 2, (f, at, v) => { b.refs[KIND_VEHICLE].put(v, f, at + 0); });
}

// The first mirrored field of `m` that is not what the export row says (a
// write JavaScript made to Rust's state without a command), or null.
export function checkVehicles(b, f, at, h, m) {
  const want = syncVehicles(b, f, at, h, new VehiclesMirror());
  if (!sameEach(m.vehicles, want.vehicles, (x, y) => Object.is(x, y))) return ".vehicles";
  return null;
}

export function sameVehicles(a, b) {
  if (!sameEach(a.vehicles, b.vehicles, (x, y) => Object.is(x, y))) return ".vehicles";
  return null;
}

export function exportVehicles(o, cx) {
  let v = cx.seen.get(o);
  if (v) return v;
  v = {};
  cx.seen.set(o, v);
  v.vehicles = o.vehicles.map((x) => exportVehicle(x, cx));
  return v;
}
